  // 运维
  var 优选IP条目 = [];
  function 解析优选IP(text) {
    var seen = {}, entry = [], 总行 = 0, 跳过 = 0;
    String(text == null ? '' : text).split(/\\r?\\n/).forEach(function (line) {
      line = line.trim();
      if (!line) return;
      总行++;
      var body = line.split('#')[0].trim();
      if (!body) { 跳过++; return; }
      var host = '', port = '443';
      if (body.charAt(0) === '[') {                    // [IPv6]:port
        var 闭 = body.indexOf(']');
        if (闭 < 0) { 跳过++; return; }
        host = body.slice(1, 闭);
        var 尾 = body.slice(闭 + 1);
        if (尾.indexOf(':') === 0 && 尾.length > 1) port = 尾.slice(1);
      } else if (body.split(':').length > 2) {
        host = body;                                   // 裸 IPv6（无端口）
      } else {
        var 冒号 = body.indexOf(':');
        host = 冒号 === -1 ? body : body.slice(0, 冒号);
        if (冒号 !== -1) port = body.slice(冒号 + 1);
      }
      host = host.trim(); port = port.trim();
      if (!host || !/^\\d+$/.test(port)) { 跳过++; return; }
      var key = host + ':' + port;
      if (seen[key]) return;
      seen[key] = 1;
      entry.push({ host: host, port: port });
    });
    优选IP条目 = entry;
    var st = $('#o-add-stats');
    if (st) st.textContent = '共 ' + 总行 + ' 行 · 去重后 ' + 优选IP条目.length + ' 条 · 样例: ' + entry.slice(0, 3).map(function (e) { return e.host + ':' + e.port; }).join(', ');
  }
