      const parts = s.split("/");
      return parts.length === 2 && /^(?:\d{1,3}\.){3}\d{1,3}$/.test(parts[0]) && parts[0].split(".").every((n) => Number(n) <= 255) && /^\d+$/.test(parts[1]) && Number(parts[1]) <= 32;
